#!/usr/bin/env node
// ─────────────────────────────────────────────────────────────────────────────
// gen_barrels.mjs — regenerate every directory index in the frontend.
//
// Why this file exists at all: Next.js 16 / Turbopack has no glob import.
// `import.meta.glob` is Vite-only and `require.context` is dead under Turbopack,
// so a directory of injected providers/extensions/routes cannot be discovered at
// build time. The barrels are therefore GENERATED AND COMMITTED — Vercel will
// not run bash — marked class:generated, regenerated by predev/prebuild so they
// self-heal, and asserted by conformance via `regen && git diff --exit-code`.
//
// Ordering is by the NN- filename prefix, then lexicographic. That prefix is the
// single source of truth for order: CSS cascade order and extension render order
// are both sensitive to it, and a number in the filename is greppable in a way an
// `export const order` is not.
//
//   providers/NN-name.tsx          → providers/index.generated.ts
//   extensions/<point>/NN-name.tsx → extensions/<point>/index.generated.ts
//   nav/<id>.nav.ts                → nav/nav.generated.ts
//   styles/layers/<id>.css         → styles/layers/index.generated.css
//
// The entry TYPES are hand-written in lib/extensions.ts and lib/nav.ts, not
// emitted here. Generated code declaring a type that hand-written code imports
// puts a cycle through the build step; see the comments in those two files.
// ─────────────────────────────────────────────────────────────────────────────

import fs from 'node:fs';
import path from 'node:path';

import { CLASSES, fail, loadManifest, parseArgs, relPath, saveManifest, writeAtomic } from './manifest.mjs';

const BANNER_TS = `// ─────────────────────────────────────────────────────────────────────────────
// GENERATED FILE — do not edit.
// Regenerate: pnpm gen:barrels   (also runs automatically on predev/prebuild)
// Source of truth: the sibling files in this directory.
// ─────────────────────────────────────────────────────────────────────────────
`;

const BANNER_CSS = `/* ─────────────────────────────────────────────────────────────────────────────
   GENERATED FILE — do not edit.
   Regenerate: pnpm gen:barrels   (also runs automatically on predev/prebuild)
   Source of truth: the sibling .css files in this directory.
   ───────────────────────────────────────────────────────────────────────────── */
`;

/** Entry files only: skip generated barrels, dotfiles, and type declarations. */
function entries(dir, exts) {
  if (!fs.existsSync(dir)) return [];
  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter((d) => d.isFile())
    .map((d) => d.name)
    .filter((n) => !n.startsWith('.'))
    .filter((n) => !n.includes('.generated.'))
    .filter((n) => !n.endsWith('.d.ts'))
    .filter((n) => exts.some((e) => n.endsWith(e)))
    .sort();
}

/** `00-theme-toggle.tsx` → { order: 0, id: 'theme-toggle', stem: '00-theme-toggle' } */
function describe(name) {
  const stem = name.replace(/\.[^.]+$/, '');
  const m = stem.match(/^(\d+)[-_](.+)$/);
  return {
    stem,
    order: m ? Number(m[1]) : 500, // unprefixed files sort into the middle
    id: m ? m[2] : stem,
  };
}

/** A valid JS identifier derived from a filename, unique per index. */
function ident(prefix, stem, i) {
  return `${prefix}${i}_${stem.replace(/[^A-Za-z0-9]/g, '_')}`;
}

// ─────────────────────────────────────────────────────────────────────────────
// Generators
// ─────────────────────────────────────────────────────────────────────────────

/**
 * providers/index.generated.ts
 *
 * Base's own ThemeProvider lives in providers/00-ThemeProvider.tsx under this
 * mechanism — no special case. That is what keeps the extension point honest:
 * if the barrel breaks, the base breaks first.
 */
function genProviders(dir) {
  const files = entries(dir, ['.tsx']);
  const items = files.map((n, i) => ({ ...describe(n), file: n, ident: ident('P', describe(n).stem, i) }));
  items.sort((a, b) => a.order - b.order || a.stem.localeCompare(b.stem));

  const lines = [BANNER_TS];
  lines.push(`import type { ReactNode } from 'react';`);
  if (items.length) {
    lines.push('');
    for (const it of items) lines.push(`import ${it.ident} from './${it.stem}';`);
  }
  lines.push('');
  lines.push(`export type ProviderComponent = (props: { children: ReactNode }) => ReactNode;`);
  lines.push('');
  lines.push(`/** Outermost first. Order comes from the NN- filename prefix. */`);
  lines.push(`export const providers: ProviderComponent[] = [`);
  for (const it of items) lines.push(`  ${it.ident} as ProviderComponent,`);
  lines.push(`];`);
  return lines.join('\n') + '\n';
}

/**
 * extensions/<point>/index.generated.ts — every JSX extension point in the
 * project. Markers inside JSX are forbidden, so this is the ONLY way to add UI
 * to a base-owned layout file.
 */
function genExtensionPoint(dir) {
  const files = entries(dir, ['.tsx']);
  const items = files.map((n, i) => ({ ...describe(n), file: n, ident: ident('E', describe(n).stem, i) }));
  items.sort((a, b) => a.order - b.order || a.stem.localeCompare(b.stem));

  const lines = [BANNER_TS];
  // `ComponentType` is only referenced by the per-entry casts below, so an empty
  // extension point must not import it — eslint fails the build on an unused
  // import, and an empty point is the normal state before anything is injected.
  if (items.length) {
    lines.push(`import type { ComponentType } from 'react';`);
    lines.push('');
  }
  lines.push(`import type { ExtensionEntry } from '@/lib/extensions';`);
  if (items.length) {
    lines.push('');
    for (const it of items) lines.push(`import ${it.ident} from './${it.stem}';`);
  }
  lines.push('');
  lines.push(`export type { ExtensionEntry };`);
  lines.push('');
  lines.push(`export const entries: ExtensionEntry[] = [`);
  for (const it of items) {
    lines.push(`  { id: ${JSON.stringify(it.id)}, order: ${it.order}, Component: ${it.ident} as ComponentType },`);
  }
  lines.push(`];`);
  lines.push('');
  lines.push(`export default entries;`);
  return lines.join('\n') + '\n';
}

/**
 * nav/nav.generated.ts
 *
 * Nav entries are DATA, not JSX, so one registry feeds the site header, a
 * sitemap, a command palette, and the conformance check that every href
 * resolves to a real page.tsx.
 */
function genNav(dir) {
  const files = entries(dir, ['.nav.ts']);
  const items = files.map((n, i) => ({ ...describe(n), file: n, ident: ident('N', describe(n).stem, i) }));
  items.sort((a, b) => a.order - b.order || a.stem.localeCompare(b.stem));

  const lines = [BANNER_TS];
  lines.push(`import type { NavEntry } from '@/lib/nav';`);
  if (items.length) {
    lines.push('');
    for (const it of items) lines.push(`import ${it.ident} from './${it.stem}';`);
  }
  lines.push('');
  lines.push(`export type { NavEntry };`);
  lines.push('');
  lines.push(`export const nav: NavEntry[] = [`);
  for (const it of items) lines.push(`  ${it.ident},`);
  lines.push(`].sort((a, b) => (a.order ?? 500) - (b.order ?? 500) || a.label.localeCompare(b.label));`);
  lines.push('');
  lines.push(`export default nav;`);
  return lines.join('\n') + '\n';
}

/**
 * styles/layers/index.generated.css
 *
 * Even the @import line is generated, so no injection ever appends to
 * globals.css — the singleton the current scripts all fight over.
 */
function genLayerCss(dir) {
  const files = entries(dir, ['.css']);
  const items = files.map(describe);
  items.sort((a, b) => a.order - b.order || a.stem.localeCompare(b.stem));

  const lines = [BANNER_CSS];
  if (items.length === 0) {
    lines.push('/* No style layers applied. */');
  } else {
    for (const it of items) lines.push(`@import "./${it.stem}.css";`);
  }
  return lines.join('\n') + '\n';
}

// ─────────────────────────────────────────────────────────────────────────────

function emit(root, outFile, contents, results) {
  const existing = fs.existsSync(outFile) ? fs.readFileSync(outFile, 'utf8') : null;
  const changed = existing !== contents;
  if (changed) writeAtomic(outFile, contents);
  results.push({ file: relPath(root, outFile), changed });
}

function run(root, { check = false, quiet = false } = {}) {
  const src = path.join(root, 'frontend', 'src');
  if (!fs.existsSync(src)) fail(`No frontend/src under ${root}`, [], 'Run the bootstrap first.');

  const results = [];

  const providersDir = path.join(src, 'providers');
  if (fs.existsSync(providersDir)) {
    emit(root, path.join(providersDir, 'index.generated.ts'), genProviders(providersDir), results);
  }

  const extensionsRoot = path.join(src, 'extensions');
  if (fs.existsSync(extensionsRoot)) {
    for (const d of fs.readdirSync(extensionsRoot, { withFileTypes: true })) {
      if (!d.isDirectory()) continue;
      const dir = path.join(extensionsRoot, d.name);
      emit(root, path.join(dir, 'index.generated.ts'), genExtensionPoint(dir), results);
    }
  }

  const navDir = path.join(src, 'nav');
  if (fs.existsSync(navDir)) {
    emit(root, path.join(navDir, 'nav.generated.ts'), genNav(navDir), results);
  }

  const layersDir = path.join(src, 'styles', 'layers');
  if (fs.existsSync(layersDir)) {
    emit(root, path.join(layersDir, 'index.generated.css'), genLayerCss(layersDir), results);
  }

  // Keep the ledger honest: generated files are class:generated, so a later
  // layer is told to edit the source of truth rather than the barrel.
  const m = loadManifest(root, { required: false });
  if (m.files) {
    for (const r of results) {
      m.files[r.file] = { class: CLASSES.generated, owner: 'base' };
    }
    saveManifest(root, m);
  }

  const stale = results.filter((r) => r.changed);
  if (check && stale.length) {
    fail(
      `${stale.length} generated barrel(s) were out of date`,
      stale.map((r) => `  ${r.file}`),
      'Run `pnpm gen:barrels` and commit the result.'
    );
  }
  if (!quiet) {
    for (const r of results) process.stdout.write(`${r.changed ? 'wrote  ' : 'ok     '} ${r.file}\n`);
  }
}

function main(argv) {
  const { flags } = parseArgs(argv);
  const root = path.resolve(flags.root && flags.root !== true ? flags.root : process.cwd());
  run(root, { check: Boolean(flags.check), quiet: Boolean(flags.quiet) });
}

if (import.meta.filename === process.argv[1]) main(process.argv.slice(2));

export { run, genProviders, genExtensionPoint, genNav, genLayerCss };
